import CreateEvent from './features/dashboard/organizer/CreateEvent';
import MyEvents from './features/dashboard/organizer/MyEvents';

function App() {
  return (
    <BrowserRouter>
      <Navbar />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/organizer/dashboard" element={<OrganizerDashboard />} />
        <Route path="/attendee/dashboard" element={<AttendeeDashboard />} />

        {/* New routes for organizer event handling */}
        <Route path="/organizer/create-event" element={<CreateEvent />} />
        <Route path="/organizer/my-events" element={<MyEvents />} />
      </Routes>
    </BrowserRouter>
  );
}
